DHT22 modülünün DATA kablosu Uno'ya bağlı DEĞİL. Bu kod 4,5 saniye çalışırsa seri monitörde ne görünür?

```
#include <DHT.h>
DHT dht(5, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  delay(2000);
  float t = dht.readTemperature();
  if (isnan(t)) Serial.println("HATA");
  else Serial.println(t * 2);
}
```

